    hp: hpEok.reduce((a, b) => a + b, 0) * 1e8,
    forceType: force?.[0] ?? null,
    forceRequired: force?.[1] ?? null,
    imageUrl: `/bosses/${slug}.png`,
    statBasis: defenseRate >= 380 ? "380" : "300",
    cut: CUTS[id],
  };
}

