// Public interface of the boss PoC. Owner: boss agent. Party PoC imports only listBosses/getBoss.
import type { Boss } from "@/lib/types";
import { BOSSES } from "./data";
import { searchBosses } from "./search";

export function listBosses(): Boss[] {
  return BOSSES;
}

export function getBoss(id: string): Boss | null {
  return BOSSES.find((b) => b.id === id) ?? null;
}

export function findBosses(q: string): Boss[] {
  return searchBosses(BOSSES, q);
}
// Pure helpers (type-only imports so `node --test` can load this file).
import type { Boss } from "@/lib/types";

export const DIFFICULTY_LABEL: Record<Boss["difficulty"], string> = {
  easy: "이지",
  normal: "노말",
  hard: "하드",
  chaos: "카오스",
  extreme: "익스트림",
};

const norm = (s: string) => s.replace(/\s+/g, "").toLowerCase();

// Every whitespace-separated token must appear in "난이도+이름+id", spaces ignored:
// "카링", "노말 카링", "카링 노말", "검은마법사", "extreme-black" all match.
export function searchBosses(bosses: Boss[], q: string): Boss[] {
  const tokens = q.trim().split(/\s+/).filter(Boolean).map(norm);
  return bosses.filter((b) => {
    const hay = norm(`${DIFFICULTY_LABEL[b.difficulty]}${b.name}${b.id}`);
    return tokens.every((t) => hay.includes(t));
  });
}

// 1073700000000 -> "1조 737억"; keeps the two largest non-zero units.
export function formatHp(n: number): string {
  const units: [number, string][] = [[1e16, "경"], [1e12, "조"], [1e8, "억"], [1e4, "만"]];
  const parts = units
    .map(([u, label]) => [Math.floor(n / u) % 10000, label] as const)
    .filter(([v]) => v > 0)
    .slice(0, 2)
    .map(([v, label]) => `${v}${label}`);
  return parts.length ? parts.join(" ") : String(n);
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { BOSSES, CUTS } from "./data.ts";
import { searchBosses, formatHp } from "./search.ts";
const bosses = BOSSES;
const ids = (q: string) => searchBosses(bosses, q).map((b) => b.id);

test("seed integrity", () => {
  assert.equal(new Set(bosses.map((b) => b.id)).size, bosses.length, "unique ids");
  assert.deepEqual(Object.keys(CUTS).sort(), bosses.map((b) => b.id).sort(), "one cut per boss");
  for (const b of bosses) {
    assert.ok(Number.isInteger(b.hp) && b.hp > 0, b.id);
    assert.equal(b.statBasis, b.defenseRate >= 380 ? "380" : "300", b.id);
    assert.ok(b.maxParty >= 1 && b.maxParty <= 6, b.id);
  }
  // cut and HP grow with difficulty within each boss (data is listed easiest first)
  for (let i = 1; i < bosses.length; i++) {
    const [a, b] = [bosses[i - 1], bosses[i]];
    if (a.name === b.name) assert.ok(b.cut > a.cut && b.hp > a.hp, `${a.id} < ${b.id}`);
  }
});

test("search", () => {
  assert.deepEqual(ids("카링"), ["easy-kaling", "normal-kaling", "hard-kaling", "extreme-kaling"]);
  assert.deepEqual(ids("카링 노말"), ["normal-kaling"]);
  assert.deepEqual(ids("익스트림 검은마법사"), ["extreme-black-mage"]);
  assert.deepEqual(ids("세렌"), ["normal-seren", "hard-seren", "extreme-seren"]);
  assert.equal(ids("").length, bosses.length);
  assert.deepEqual(ids("없는보스"), []);
});

test("formatHp", () => {
  assert.equal(formatHp(1_073_700_000_000), "1조 737억");
  assert.equal(formatHp(822_000_000_000), "8220억");
  assert.equal(formatHp(45_400_000_000_000_000), "4경 5400조");
  assert.equal(formatHp(17_800_000_000_000), "17조 8000억");
});

